const sourcePhraseKeys = Object.fromEntries(Object.keys(phraseRows).map((source) => [source, `phrase:${source}`]));
const phraseCatalogs = Object.fromEntries(LANGUAGES.map(({ code }, index) => [code,
  Object.fromEntries(Object.entries(phraseRows).map(([source, values]) => [`phrase:${source}`, values[index]])),
]));
export function translateRole(language, role) {
  const index = roleValues.indexOf(String(role || '').toLowerCase());
  return index < 0 ? role : (roleNames[language] || roleNames.sq)[index];
}
